import { constants } from "node:fs";
import { open } from "node:fs/promises";

// Binary age v1 files generated by backup-encrypted.sh begin with this marker.
// Header validation detects obvious plaintext mislabels; only full decryption
// with the offline identity can establish that ciphertext is decryptable.
const AGE_V1_HEADER = Buffer.from("age-encryption.org/v1\n", "ascii");

export async function assertAgeV1Header(path) {
  const handle = await open(path, constants.O_RDONLY | constants.O_NOFOLLOW);
  try {
    const header = Buffer.alloc(AGE_V1_HEADER.length);
    const { bytesRead } = await handle.read(header, 0, header.length, 0);
    if (bytesRead !== header.length || !header.equals(AGE_V1_HEADER)) {
      throw new Error("EDGE_SYNC_AGE_HEADER_INVALID");
    }
  } finally {
    await handle.close();
  }
}
